"""Hand-verified tests for main.py (run: python3 test_solution.py)."""
import json, struct, subprocess, sys, zlib, pathlib

HERE = pathlib.Path(__file__).resolve().parent

def rec(seq, kind, txid, payload=b"", plen=None, crc=None):
    pl = len(payload) if plen is None else plen
    body = struct.pack("<IIBI", pl, seq, kind, txid) + payload
    c = zlib.crc32(body) & 0xFFFFFFFF if crc is None else crc
    return body + struct.pack("<I", c)

def patch_rec(seq, txid, page, off, data):
    payload = struct.pack("<HHH", page, off, len(data)) + data
    return rec(seq, 2, txid, payload)

def commit_rec(seq, txid, count, digest):
    return rec(seq, 3, txid, struct.pack("<II", count, digest))

def digest_of(*patch_payloads):
    return zlib.crc32(b"".join(patch_payloads)) & 0xFFFFFFFF

def solve(req):
    p = subprocess.run([sys.executable, str(HERE / "main.py")],
                       input=json.dumps(req) + "\n", text=True, capture_output=True, cwd=HERE)
    assert p.returncode == 0, p.stderr
    return json.loads(p.stdout.splitlines()[0])

def expect(name, req, pages, vb, ls):
    got = solve(req)
    exp = {"pages": pages, "valid_bytes": vb, "last_seq": ls}
    if got != exp:
        print("FAIL", name)
        print("  got", got)
        print("  exp", exp)
        return False
    return True

